import { randomUUID } from "node:crypto";
import { Pool } from "pg";
import { ObjectStore } from "./objectStore";

export interface UploadTicket {
  videoId: string;
  objectKey: string;
  uploadUrl: string;
  expiresAt: Date;
}

export class UploadError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

const MAX_BYTES = 10 * 1024 ** 3;

export class VideoUploadService {
  constructor(private readonly db: Pool, private readonly store: ObjectStore) {}

  async begin(tenantId: string, title: string): Promise<UploadTicket> {
    const videoId = randomUUID();
    const objectKey = `${tenantId}/raw/${videoId}.mp4`;
    const expiresAt = new Date(Date.now() + 15 * 60 * 1000);
    await this.db.query(
      `INSERT INTO videos (id, tenant_id, title, status, object_key)
       VALUES ($1, $2, $3, 'uploading', $4)`,
      [videoId, tenantId, title, objectKey],
    );
    const uploadUrl = await this.store.presignPut(objectKey, expiresAt);
    return { videoId, objectKey, uploadUrl, expiresAt };
  }

  async complete(tenantId: string, videoId: string, objectKey: string): Promise<void> {
    if (!objectKey.startsWith(tenantId)) {
      throw new UploadError("object key outside tenant namespace", 403);
    }
    const head = await this.store.head(objectKey);
    if (!head) throw new UploadError("object not found", 404);
    if (head.size > MAX_BYTES) throw new UploadError("object too large", 413);

    const res = await this.db.query(
      `UPDATE videos
          SET status = 'processing', object_key = $3, size_bytes = $4
        WHERE id = $1 AND tenant_id = $2 AND status = 'uploading'`,
      [videoId, tenantId, objectKey, head.size],
    );
    if (res.rowCount === 0) throw new UploadError("no pending upload for this video", 409);
    await this.store.enqueueTranscode({ tenantId, videoId, objectKey });
  }
}

export interface ObjectHead {
  size: number;
  contentType: string;
}

export interface TranscodeJob {
  tenantId: string;
  videoId: string;
  objectKey: string;
}

export interface ObjectStore {
  presignPut(key: string, expiresAt: Date): Promise<string>;
  head(key: string): Promise<ObjectHead | null>;
  enqueueTranscode(job: TranscodeJob): Promise<void>;
}

import express from "express";
import { Pool } from "pg";
import { ObjectStore } from "./objectStore";
import { UploadError, VideoUploadService } from "./videoUploadService";

type TenantResolver = (apiKey: string) => Promise<string | null>;

export function uploadRoutes(db: Pool, store: ObjectStore, resolveTenant: TenantResolver) {
  const service = new VideoUploadService(db, store);
  const router = express.Router();
  router.use(express.json({ limit: "8kb" }));

  router.use(async (req, res, next) => {
    const apiKey = req.header("x-api-key");
    const tenantId = apiKey ? await resolveTenant(apiKey) : null;
    if (!tenantId) return res.status(401).json({ error: "invalid api key" });
    res.locals.tenantId = tenantId;
    next();
  });

  router.post("/uploads", async (req, res, next) => {
    try {
      const title = typeof req.body?.title === "string" ? req.body.title.slice(0, 200) : "";
      if (!title) return res.status(400).json({ error: "title required" });
      const ticket = await service.begin(res.locals.tenantId, title);
      res.status(201).json(ticket);
    } catch (err) {
      next(err);
    }
  });

  router.post("/uploads/:videoId/complete", async (req, res, next) => {
    try {
      const objectKey = req.body?.objectKey;
      if (typeof objectKey !== "string") return res.status(400).json({ error: "objectKey required" });
      await service.complete(res.locals.tenantId, req.params.videoId, objectKey);
      res.status(202).json({ status: "processing" });
    } catch (err) {
      if (err instanceof UploadError) return res.status(err.status).json({ error: err.message });
      next(err);
    }
  });

  return router;
}
